head.script:
// 테스트 설명, 유효성 값 설정
//  - _1 : 표시 방향과 컴포넌트 주변 공간 (auto / 미설정 / down / up)
//  - _2 : up 일 때의 slideDown 애니메이션
//  - _3 : fit 과 아이템 정의 방식 (auto 대조)
scwin.tData = {
    "description" : "[autoComplete > P > direction]<br/>AutoComplete 컴포넌트의 아이템 리스트창이 표시되는 방향을 설정합니다.",
    "validation" : [
        "fit 설정 시, 아이템이 GridViewItemSet 으로 정의된 경우 아이템 리스트창의 너비가 컴포넌트 왼쪽 끝부터 웹브라우저 화면 오른쪽 끝까지로 설정되며, 표시 방향은 'auto' 와 같은 기준으로 적용됩니다.",
        "fit 설정 시, 아이템이 ItemSet 또는 BindItemSet 으로 정의된 경우 'down' 으로 동작합니다.",
    ]
}



// 확인 버튼을 누르는 순간의 리스트창 상태 (버튼 클릭으로 리스트창이 닫히기 전에 기록)
scwin.gVar = { "snap" : null };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 아이템 DataList 생성 (BindItemSet / GridViewItemSet 용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON([
        { "label" : "Seoul", "value" : "1" },
        { "label" : "Busan", "value" : "2" },
        { "label" : "Incheon", "value" : "3" },
        { "label" : "Sejong", "value" : "4" }
    ]);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_direction.setValue("fit");
    con_itemset.setValue("gridViewItemset");
    con_position.setValue("default");

    // 확인 버튼 클릭 시 리스트창이 닫히므로, 닫히기 전(mousedown)에 리스트창 상태를 기록
    btn_getListPosition.render.addEventListener("mousedown", scwin.captureListState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    scwin.gVar.snap = null;

    $c.gcm.createLabel('label="[전제] 컴포넌트 위치 = 화면 하단 : 컴포넌트를 화면 아래쪽 끝에 고정 (하단에 리스트창이 표시될 공간 없음)\n[절차] 화살표 버튼 클릭으로 리스트창 열기 -> 리스트창이 열린 상태에서 확인 버튼"', '', 'label1');

    let properties = {
        direction : con_direction.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    // 컴포넌트 위치 : 화면 크기와 무관하게 화면 아래쪽 끝 기준으로 고정
    let strStyle = "width:200px; height:30px;";
    if (con_position.getValue() === "bottom") {
        strStyle += " position:fixed; bottom:5px;";
    }

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="' + strStyle + '">';
    strTarget += '<w2:choices>';
    if (con_itemset.getValue() === "gridViewItemset") {
        // GridViewItemSet
        strTarget += '<w2:gridViewItemset nodeset="data:dlt_city" label="label" value="value">';
        strTarget += '<w2:item ref="label" header="label"></w2:item>';
        strTarget += '<w2:item ref="value" header="value"></w2:item>';
        strTarget += '</w2:gridViewItemset>';
    } else if (con_itemset.getValue() === "bindItemset") {
        // BindItemSet (DataList 바인딩)
        strTarget += '<w2:itemset nodeset="data:dlt_city">';
        strTarget += '<w2:label ref="label"></w2:label>';
        strTarget += '<w2:value ref="value"></w2:value>';
        strTarget += '</w2:itemset>';
    } else {
        // ItemSet (아이템 직접 정의)
        let arrCity = ["Seoul", "Busan", "Incheon", "Sejong"];
        for (let i = 0; i < arrCity.length; i++) {
            strTarget += '<w2:item>';
            strTarget += '<w2:label>' + arrCity[i] + '</w2:label>';
            strTarget += '<w2:value>' + (i + 1) + '</w2:value>';
            strTarget += '</w2:item>';
        }
    }
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
};



// 확인 버튼을 누르는 순간의 리스트창 상태 기록
scwin.captureListState = function (e) {
    scwin.gVar.snap = null;
    if (typeof target1 === 'undefined') {
        return;
    }
    // 아이템 리스트창 요소 (ItemSet / BindItemSet : _itemTable, GridViewItemSet : _gridViewItemTable)
    let listElem = document.querySelector("[id='" + target1.id + "_itemTable'], [id='" + target1.id + "_gridViewItemTable']");
    if (!listElem) {
        return;
    }
    let objStyle = getComputedStyle(listElem);
    if (objStyle.display === "none" || objStyle.visibility === "hidden") {
        return;
    }

    let rectList = listElem.getBoundingClientRect();
    let rectComp = target1.render.getBoundingClientRect();

    scwin.gVar.snap = {
        "downSpace" : (document.documentElement.clientHeight - rectComp.bottom >= rectList.height) ? "있음" : "없음",
        "direction" : (rectList.top < rectComp.top) ? "컴포넌트 상단" : "컴포넌트 하단",
        "leftSame" : Math.abs(rectList.left - rectComp.left) <= 1,
        "rightSame" : Math.abs(rectList.right - document.documentElement.clientWidth) <= 1
    };
};



// 리스트창 표시 방향과 너비 범위 출력 (validation 1, 2)
scwin.btn_getListPosition_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let snap = scwin.gVar.snap;
    if (!snap) {
        bottom.setReturnValue("리스트창 열림 : false");
        return;
    }

    // 컴포넌트 주변 공간과 표시 방향
    bottom.setReturnValue("아이템 정의 : " + con_itemset.getText() + " / direction : " + con_direction.getValue() + " / 하단 공간 : " + snap.downSpace + " -> 리스트창 표시 방향 : " + snap.direction);

    // 리스트창 너비 범위 (컴포넌트 왼쪽 끝 ~ 화면 오른쪽 끝)
    bottom.setReturnValue("리스트창 왼쪽 끝이 컴포넌트 왼쪽 끝과 일치 : " + snap.leftSame + " / 리스트창 오른쪽 끝이 화면 오른쪽 끝과 일치 : " + snap.rightSame);
};
